private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        return -1;
    }
    for (int i = end; i >= 0; i--) {
        if (headerPart.charAt(i) == '\n') {
            if (i > 0 && headerPart.charAt(i - 1) == '\r') {
                return i - 1;
            }
            return i;
        }
    }
    return -1;
}

