    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Get the number of vertices in each partition
        int n = (Integer) parameters.get("n");
        int m = (Integer) parameters.get("m");

        // Create vertices for the first partition
        for (int i = 0; i < n; i++) {
            String vertexName = "u" + i;
            V vertex = target.addVertex();
            resultMap.put(vertexName, vertex);
        }

        // Create vertices for the second partition
        for (int j = 0; j < m; j++) {
            String vertexName = "v" + j;
            V vertex = target.addVertex();
            resultMap.put(vertexName, vertex);
        }

        // Add edges between every vertex in the first partition and every vertex in the second partition
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                V u = resultMap.get("u" + i);
                V v = resultMap.get("v" + j);
                target.addEdge(u, v);
            }
        }
    }
