public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return new Mappings();
    }

    Mappings result = new Mappings();

    // Get the current mappings for the table
    Mappings currentMappings = getCurrentMappings(tableName);
    if (currentMappings == null) {
        return mappings;
    }

    // Get fields from input mappings
    Map<String, Object> inputFields = mappings.getFields();
    if (inputFields == null || inputFields.isEmpty()) {
        return result;
    }

    // Get fields from current mappings
    Map<String, Object> currentFields = currentMappings.getFields();
    if (currentFields == null) {
        currentFields = new HashMap<>();
    }

    // Find fields that exist in input mappings but not in current mappings
    for (Map.Entry<String, Object> entry : inputFields.entrySet()) {
        String fieldName = entry.getKey();
        // Skip _source field to avoid current index update conflict
        if ("_source".equals(fieldName)) {
            continue;
        }

        if (!currentFields.containsKey(fieldName)) {
            result.addField(fieldName, entry.getValue());
        }
    }

    return result;
}

