static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    // Extract year, month, day from the timeBucket (format: YYYYMMDD)
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Validate month and day
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month: " + month);
    }
    if (day < 1 || day > 31) {
        throw new IllegalArgumentException("Invalid day: " + day);
    }

    // Calculate the first day of the current month
    long firstDayOfMonth = year * 10000L + month * 100L + 1;

    // Calculate the number of days from the first day of the month to the current day
    int daysFromStart = day - 1;

    // Calculate the bucket index (0-based)
    int bucketIndex = daysFromStart / dayStep;

    // Calculate the start day of the bucket
    int bucketStartDay = bucketIndex * dayStep + 1;

    // If the bucket start day exceeds the number of days in the month, clamp to the last day of the month
    // We need to know the number of days in the month
    int daysInMonth;
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31;
            break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30;
            break;
        case 2:
            // Check for leap year
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                daysInMonth = 29;
            } else {
                daysInMonth = 28;
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid month: " + month);
    }

    if (bucketStartDay > daysInMonth) {
        bucketStartDay = daysInMonth;
    }

    // Construct the compressed time bucket
    return year * 10000L + month * 100L + bucketStartDay;
}

