        throw new IllegalArgumentException("Invalid start or end index");
    }
    for (int i = start; i < end; i++) {
        int type = currentFrame[i];
        if (type == Opcodes.TOP) {
            stackMapTableEntries.putShort(Opcodes.TOP);
        } else if (type == Opcodes.INTEGER) {
            stackMapTableEntries.putShort(Opcodes.INTEGER);
        } else if (type == Opcodes.FLOAT) {
            stackMapTableEntries.putShort(Opcodes.FLOAT);
        } else if (type == Opcodes.LONG) {
            stackMapTableEntries.putShort(Opcodes.LONG);
        } else if (type == Opcodes.DOUBLE) {
            stackMapTableEntries.putShort(Opcodes.DOUBLE);
        } else if (type == Opcodes.NULL) {
            stackMapTableEntries.putShort(Opcodes.NULL);
        } else if (type == Opcodes.UNINITIALIZED_THIS) {
            stackMapTableEntries.putShort(Opcodes.UNINITIALIZED_THIS);
        } else if (type >= 0) {
            // It's a class type, represented by an index into the constant pool
            stackMapTableEntries.putShort(Opcodes.ITEM_CLASS);
            stackMapTableEntries.putShort(type);
        } else {
            // It's an uninitialized type, represented by an offset
            stackMapTableEntries.putShort(Opcodes.ITEM_UNINITIALIZED);
            stackMapTableEntries.putShort(type);
        }
    }
}

