@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (type == null) {
        throw new IllegalArgumentException("Type cannot be null");
    }
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            } else {
                throw new IllegalArgumentException("Cannot convert string of length " + str.length() + " to Character");
            }
        } else if (value instanceof Number) {
            return (char) ((Number) value).intValue();
        } else {
            throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character");
        }
    }
    throw new IllegalArgumentException("Unsupported type: " + type.getName());
