final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        // Read the length of the UTF-8 string (2 bytes)
        int length = readUnsignedShort();

        // Read the UTF-8 encoded bytes
        byte[] utf8Bytes = new byte[length];
        for (int i = 0; i < length; i++) {
            utf8Bytes[i] = readByte();
        }

        // Decode the UTF-8 bytes into characters
        int charIndex = 0;
        int byteIndex = 0;
        while (byteIndex < length) {
            int b1 = utf8Bytes[byteIndex] & 0xFF;
            int codePoint;
            int numBytes;

            if (b1 < 0x80) {
                // 1-byte character
                codePoint = b1;
                numBytes = 1;
            } else if ((b1 & 0xE0) == 0xC0) {
                // 2-byte character
                codePoint = b1 & 0x1F;
                numBytes = 2;
            } else if ((b1 & 0xF0) == 0xE0) {
                // 3-byte character
                codePoint = b1 & 0x0F;
                numBytes = 3;
            } else if ((b1 & 0xF8) == 0xF0) {
                // 4-byte character
                codePoint = b1 & 0x07;
                numBytes = 4;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding");
            }

            for (int i = 1; i < numBytes; i++) {
                int b = utf8Bytes[byteIndex + i] & 0xFF;
                if ((b & 0xC0) != 0x80) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding");
                }
                codePoint = (codePoint << 6) | (b & 0x3F);
            }

            byteIndex += numBytes;

            // Handle surrogate pairs for characters outside the Basic Multilingual Plane
            if (codePoint > 0xFFFF) {
                codePoint -= 0x10000;
                charBuffer[charIndex++] = (char) (0xD800 + (codePoint >> 10));
                charBuffer[charIndex++] = (char) (0xDC00 + (codePoint & 0x3FF));
            } else {
                charBuffer[charIndex++] = (char) codePoint;
            }
        }

        return new String(charBuffer, 0, charIndex);
    } catch (Exception e) {
        throw new RuntimeException("Error reading UTF-8 constant pool entry", e);
    }
}
