private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    while (true) {
        int c = read();
        if (c == -1) {
            break;
        }
        char ch = (char) c;
        boolean isTerminator = false;
        for (char terminator : terminators) {
            if (ch == terminator) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        token.append(ch);
    }
    return token.toString();
}
