        return;
    }
    ListNode<E> node = list.head;
    while (node != null) {
        ListNode<E> next = node.next;
        // Remove from the source list
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            list.head = node.next;
        }
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            list.tail = node.prev;
        }
        // Add to this list
        node.prev = this.tail;
        node.next = null;
        if (this.tail != null) {
            this.tail.next = node;
        } else {
            this.head = node;
        }
        this.tail = node;
        node = next;
    }
    list.head = null;
    list.tail = null;
}
