public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the base path: ensure it ends with a separator if it's a directory
    // If the base path is empty, treat it as root
    String normalizedPath = path;
    if (!normalizedPath.isEmpty() && !normalizedPath.endsWith("/")) {
        normalizedPath = normalizedPath + "/";
    }

    // Handle the relative path
    String result = normalizedPath + relativePath;

    // Normalize the result: remove redundant separators and resolve . and ..
    // Split by "/"
    String[] parts = result.split("/");
    List<String> stack = new ArrayList<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            }
        } else {
            stack.add(part);
        }
    }

    // Reconstruct the path
    if (stack.isEmpty()) {
        return "/";
    }

    StringBuilder sb = new StringBuilder();
    for (String part : stack) {
        sb.append("/").append(part);
    }

    return sb.toString();
}
