public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return result;
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                ThreadSnapshot snapshot = parseThreadSnapshot(line);
                if (snapshot != null && isWithinTimeRange(snapshot, timeRanges)) {
                    result.add(snapshot);
                }
            } catch (Exception e) {
                // Skip malformed lines
            }
        }
    }
    return result;
}

private static ThreadSnapshot parseThreadSnapshot(String line) {
    // Assuming a specific format, e.g., "timestamp|threadName|state|..."
    // This is a placeholder implementation; adjust based on actual format.
    String[] parts = line.split("\\|");
    if (parts.length < 3) {
        return null;
    }
    try {
        long timestamp = Long.parseLong(parts[0]);
        String threadName = parts[1];
        String state = parts[2];
        return new ThreadSnapshot(timestamp, threadName, state);
    } catch (NumberFormatException e) {
        return null;
    }
}

private static boolean isWithinTimeRange(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> timeRanges) {
    long ts = snapshot.getTimestamp();
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (ts >= range.getStartTime() && ts <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}
